Theoretical mock-up of what usage would look a bit like internally PyTorch:
class ProfileEvent
{
    // backwards compat
    double cpuUs() const {
        return measurements_.get<wall_clock>()->get() / 1000.0;
    }

    template <typename... Args>
    void start(Args&&... args)
    {
        // the bundlers can take any input and template meta-programming will figure out
        // which components have "start()" member functions and which have "start(...)" with given args.
        measurements_.start(std::forward<Args>(args)...);
    }

    using measurements_t = tim::lightweight_tuple<wall_clock, cpu_clock, cuda_event, flops, ...>;
    measurements_t measurements_;
};
