  int64_t cpu_ns_ = 0;
  int64_t cpu_memory_usage_ = 0;
  int64_t cuda_memory_usage_ = 0;
  int64_t cuda_us_ = -1;
  uint64_t flops_ = 0;
and are removed in favor of the aforementioned components. Here are some samples of what components generally look like:
// gist of a component definition
struct wall_clock
{
    using value_type = int64_t;
    void start() { cpu_ns_ = getTime(); }
    void stop() { cpu_ns_ = (getTime() - cpu_ns_); }
    int64_t get() const { return cpu_ns_; }
    int64_t cpu_ns_ = 0;
};

